Submit Viral Load Request.code:
// Send a viral load test request for one sample to the lab.
postViralLoadRequest({
  siteid: $.data.siteId, // the facility's IBIPIMO site id
  samples: [
    {
      sidainfo_uid: $.data.sidainfoUid, // id in the EMR (SIDAInfo)
      p_code: $.data.patientCode,
      p_name: $.data.lastName,
      p_prename: $.data.firstName,
      p_sex: $.data.sex, // 'M' | 'F'
      p_dob: $.data.dateOfBirth, // 'YYYY-MM-DD'
      arv_start_date: $.data.arvStartDate,
      date_blood_taken: $.data.collectedAt, // 'YYYY-MM-DD HH:mm:ss'
      reason_vl: 'suspicion_echec',
      on_arv: '1',
      sample_type: 'DBS',
    },
  ],
});

Submit Batch Of Viral Load Requests.code:
// Send every sample in the incoming EMR export in one request.
postViralLoadRequest({
  siteid: $.data.siteId,
  samples: $.data.samples.map(s => ({
    sidainfo_uid: s.id,
    p_code: s.patientCode,
    p_name: s.lastName,
    p_prename: s.firstName,
    p_sex: s.sex,
    p_dob: s.dateOfBirth,
    date_blood_taken: s.collectedAt,
    sample_type: s.sampleType, // e.g. 'DBS' or 'Plasma'
  })),
});

Check Viral Load Submission.code:
// After postViralLoadRequest(), pull out saved sample ids and errors.
processViralLoadSubmission((state, processSubmission) => {
  const result = processSubmission(state.data);
  if (result.hasErrors) {
    console.log(`${result.errorCount} samples were rejected`);
    return { ...state, errors: result.errors };
  }
  // Lab sample ids to store back in the EMR.
  return { ...state, labSampleIds: result.sampleIds };
});

Get Viral Load Results.code:
// Ask the lab for results of samples sent earlier.
getViralLoadResults({
  siteid: $.data.siteId,
  sample_uids: $.data.sampleUids, // e.g. ['2026010401', '2026010402']
});

Process Viral Load Results.code:
// After getViralLoadResults(), split published results from pending samples.
processViralLoadResults((state, processResults) => {
  const processed = processResults(state.data);
  console.log(`Found ${processed.totalFound}/${processed.totalRequested} results`);
  return {
    ...state,
    readyForEmr: processed.availableResults, // write these back to the EMR
    pendingSamples: processed.pendingSamples, // retry on the next run
  };
});

Get Sample Statuses.code:
// List the processing status of a site's samples.
get('/api/v1/samples/status', {
  query: { siteid: $.data.siteId },
});

List Active Sites.code:
// List active sites, e.g. to map EMR facilities to IBIPIMO site ids.
get('/api/v1/sites', {
  query: { active: true },
});
